var gDZSJGameFlow = (function () {
    var FIRST_REVEAL_MIN_DELAY = 1.0;

    var state = {
        root: null,
        bg: null,
        start: null,
        difficulty: null,
        end: null,
        diffList: null,
        resultLabel: null,
        pendingStage: null,
        pendingData: null,
        lastSeq: 0,
        initTime: 0,
        firstRevealDone: false,
        preloadUntil: 0
    };

    function NowSeconds() {
        if (typeof Game !== "undefined" && typeof Game.GetGameTime === "function") {
            return Game.GetGameTime();
        }
        return Date.now() / 1000;
    }

    function ResolveRootPanel() {
        var ctx = $.GetContextPanel();
        if (!ctx) return null;

        if (ctx.id === "GameFlowRoot") return ctx;

        var found = ctx.FindChildTraverse("GameFlowRoot");
        if (found) return found;

        var parent = ctx.GetParent();
        while (parent) {
            if (parent.id === "GameFlowRoot") return parent;
            found = parent.FindChildTraverse("GameFlowRoot");
            if (found) return found;
            parent = parent.GetParent();
        }

        return null;
    }

    function CachePanels() {
        if (!state.root) {
            state.root = ResolveRootPanel();
        }
        if (!state.root) return false;

        if (!state.start) {
            state.start = state.root.FindChildTraverse("StartGameRoot");
        }
        if (!state.bg) {
            state.bg = state.root.FindChildTraverse("GameFlowBG");
        }
        if (!state.difficulty) {
            state.difficulty = state.root.FindChildTraverse("DifficultyRoot");
        }
        if (!state.end) {
            state.end = state.root.FindChildTraverse("EndGameRoot");
        }
        if (!state.diffList) {
            state.diffList = state.root.FindChildTraverse("DifficultyList");
        }
        if (!state.resultLabel) {
            state.resultLabel = state.root.FindChildTraverse("ResultLabel");
        }

        return state.start && state.difficulty && state.end;
    }

    function HideAllContentPanels() {
        if (state.start) state.start.AddClass("Hidden");
        if (state.difficulty) state.difficulty.AddClass("Hidden");
        if (state.end) state.end.AddClass("Hidden");
    }

    function HideWholeFlow() {
        if (state.root) {
            state.root.AddClass("Hidden");
        }
    }

    function ApplyStageNow(stageName, data) {
        if (!CachePanels()) return;

        if (stageName === "hidden") {
            HideAllContentPanels();
            HideWholeFlow();
            state.root.AddClass("FlowPreload");
            if (typeof state.root.SetAcceptsInput === "function") {
                state.root.SetAcceptsInput(false);
            }
            return;
        }

        state.root.RemoveClass("Hidden");
        state.root.RemoveClass("FlowPreload");
        if (typeof state.root.SetAcceptsInput === "function") {
            state.root.SetAcceptsInput(true);
        }
        HideAllContentPanels();

        if (stageName === "difficulty") {
            state.difficulty.RemoveClass("Hidden");
            var unlockData = CustomNetTables.GetTableValue("account", "difficulty_unlock");
            UpdateDifficultyButtons(unlockData);
            return;
        }

        if (stageName === "end") {
            state.end.RemoveClass("Hidden");
            if (state.resultLabel) {
                state.resultLabel.text = (data && data.result) ? data.result : "";
            }
            return;
        }

        state.start.RemoveClass("Hidden");
    }

    function TryApplyPendingStage() {
        if (!state.pendingStage) return;
        if (!CachePanels()) return;

        if (state.pendingStage !== "hidden" && !state.firstRevealDone) {
            if (NowSeconds() < state.preloadUntil) {
                return;
            }
        }

        var nextStage = state.pendingStage;
        var nextData = state.pendingData;
        state.pendingStage = null;
        state.pendingData = null;
        ApplyStageNow(nextStage, nextData);

        if (nextStage !== "hidden") {
            state.firstRevealDone = true;
        }
    }

    function SetPendingStage(stageName, data) {
        state.pendingStage = stageName;
        state.pendingData = data || {};
        TryApplyPendingStage();
    }

    function StartPreloadGateTick() {
        (function Tick() {
            TryApplyPendingStage();
            if (!state.firstRevealDone) {
                $.Schedule(0.03, Tick);
            }
        })();
    }

    function ShowStartGame(data) {
        SetPendingStage("start", data);
    }

    function ShowDifficultySelect(data) {
        SetPendingStage("difficulty", data);
    }

    function ShowEndGame(data) {
        SetPendingStage("end", data);
    }

    function ShowHidden() {
        SetPendingStage("hidden", {});
    }

    function OnAccountData(tableName, key, data) {
        if (tableName !== "account" || key !== "difficulty_unlock") return;
        UpdateDifficultyButtons(data);
    }

    function OnGameFlowState(tableName, key, data) {
        if (tableName !== "game_flow" || key !== "state" || !data) return;

        var seq = Number(data.seq) || 0;
        if (seq > 0 && seq < state.lastSeq) return;
        if (seq > 0) {
            state.lastSeq = seq;
        }

        var phase = data.phase || "start";
        if (phase === "difficulty") {
            SetPendingStage("difficulty", data);
            return;
        }
        if (phase === "end") {
            SetPendingStage("end", data);
            return;
        }
        if (phase === "hidden") {
            SetPendingStage("hidden", data);
            return;
        }
        SetPendingStage("start", data);
    }

    function UpdateDifficultyButtons(data) {
        if (!CachePanels() || !state.diffList) return;

        state.diffList.RemoveAndDeleteChildren();

        var unlocked = (data && data.level) || 1;
        for (var i = 1; i <= 10; i++) {
            var btn = $.CreatePanel("Button", state.diffList, "diff" + i);
            btn.AddClass("DifficultyButton");
            if (i > unlocked) btn.AddClass("Locked");

            var label = $.CreatePanel("Label", btn, "");
            label.SetDialogVariable("level", String(i));

            var levelText = $.Localize("#GameLevelFmt", label);
            if (!levelText || levelText === "#GameLevelFmt") {
                levelText = $.Localize("#GameLevel") + " " + i;
            }

            levelText = String(levelText)
                .replace(/%level%/g, String(i))
                .replace(/\{(?:s|d|f):level\}/g, String(i));
            label.text = levelText;

            if (i <= unlocked) {
                (function (level, panel) {
                    panel.SetPanelEvent("onactivate", function () {
                        SelectDifficulty(level);
                    });
                })(i, btn);
            }
        }
    }

    function OnClickStartGame() {
        if (CachePanels()) {
            state.start.AddClass("Hidden");
        }
        GameEvents.SendCustomGameEventToServer("show_difficulty", {});
    }

    function SelectDifficulty(level) {
        GameEvents.SendCustomGameEventToServer("select_difficulty", { level: level });
        if (CachePanels()) {
            state.difficulty.AddClass("Hidden");
            state.root.AddClass("Hidden");
        }
    }

    function OnClickEndGame() {
        if (CachePanels()) {
            state.end.AddClass("Hidden");
        }
        GameEvents.SendCustomGameEventToServer("show_start", {});
    }

    function Init() {
        state.initTime = NowSeconds();
        state.preloadUntil = state.initTime + FIRST_REVEAL_MIN_DELAY;

        if (CachePanels()) {
            HideAllContentPanels();
            state.root.RemoveClass("Hidden");
            state.root.AddClass("FlowPreload");
            if (typeof state.root.SetAcceptsInput === "function") {
                state.root.SetAcceptsInput(false);
            }
        }
        StartPreloadGateTick();

        GameEvents.Subscribe("showStartGame", ShowStartGame);
        GameEvents.Subscribe("showDifficultySelect", ShowDifficultySelect);
        GameEvents.Subscribe("game_end", ShowEndGame);
        CustomNetTables.SubscribeNetTableListener("account", OnAccountData);
        CustomNetTables.SubscribeNetTableListener("game_flow", OnGameFlowState);
        GameEvents.SendCustomGameEventToServer("request_game_flow_state", {});

        var flowState = CustomNetTables.GetTableValue("game_flow", "state");
        if (flowState) {
            OnGameFlowState("game_flow", "state", flowState);
        } else {
            SetPendingStage("start", {});
        }
    }

    Init();

    return {
        OnClickStartGame: OnClickStartGame,
        OnClickEndGame: OnClickEndGame
    };
})();

function OnClickStartGame() {
    gDZSJGameFlow.OnClickStartGame();
}

function OnClickEndGame() {
    gDZSJGameFlow.OnClickEndGame();
}

